CustomField.formula:
if (isblank (Start_Date__c), NULL, 
if (not(isblank(Placement_Number__c)) && Start_Date__c < date(2000,1,1), left(text(Placement_Year__c), 2)&"19"&right(text(Placement_Year__c), 2),
if (not(isblank(Placement_Number__c)), left(text(Placement_Year__c), 2)&"20"&right(text(Placement_Year__c), 2),
if (Start_Date__c < date(2012,1,1), "CY" & right (text (year (Start_Date__c)), 4),
if (month (Start_Date__c) <= 6, "FY" & right (text (year (Start_Date__c)), 4),
"FY" & right (text (year (Start_Date__c)+1),4))))))
